/** Os compassos `from` a `from + bars - 1` da harmonia de uma gravação: a base de uma parte do solo. */
function songBars(base: Base, from: number, bars: number): Base {
  const at = (i: number) => (from + i) % base.prog.length;
  const split: Record<number, number[]> = {};
  for (let i = 0; i < bars; i++) {
    const parts = base.split?.[at(i)];
    if (parts) split[i] = parts;
  }
  return { ...base, prog: Array.from({ length: bars }, (_, i) => base.prog[at(i)]!), split };
}
